updateAnalyticsConsent = onCall(
  callableOptions,
  async (request): Promise<{enabled: boolean; consentID: string}> => {
    const input = parseAnalyticsConsentMutation(request.data);
    const auth = input.enabled
      ? await requireVerifiedActiveUser(request)
      : requireVerifiedAuth(request);
    await persistAnalyticsConsentMutation(auth.uid, input);
    return {enabled: input.enabled, consentID: input.consentID};
  }
)

cleanupAnalyticsAggregates = onSchedule(
  {
    schedule: "every day 03:30",
    timeZone: "Europe/Vienna",
    // Keep the production function's original region. Firebase cannot move a
    // deployed function in place, and a region change could leave two cleanup
    // schedules active during the analytics cutover.
    region: "europe-west1",
    maxInstances: 1,
    timeoutSeconds: 540,
    memory: "512MiB",
  },
  async () => {
    const database = getFirestore();
    const schemaState = await loadAnalyticsSchemaGateState(database);
    if (schemaState?.status !== "complete") {
      logger.warn("Analytics aggregate cleanup paused for schema transition.", {
        schemaVersion: schemaState?.schemaVersion ?? null,
        cutoverStatus: schemaState?.status ?? "missing-or-invalid",
      });
      return;
    }
    const cutoffDocumentID = aggregateRetentionCutoffDocumentID(
      new Date(),
      retentionDays,
    );
    const summaries: CollectionCleanupSummary[] = [];

    // Each collection has an independent cursor and budget. A malformed or
    // undeletable document therefore cannot permanently block later roots, and
    // a busy collection cannot consume the budget of the remaining collections.
    for (const collectionPath of aggregateCollectionPaths) {
      try {
        summaries.push(await cleanupAggregateCollection(
          database,
          collectionPath,
          cutoffDocumentID,
        ));
      } catch (error) {
        logger.error("Analytics aggregate collection cleanup failed.", {
          collectionPath,
          cutoffDocumentID,
          error,
        });
      }
    }

    logger.info("Analytics aggregate cleanup completed.", {
      retentionDays,
      cutoffDocumentID,
      scannedAggregateRoots: summaries.reduce(
        (total, summary) => total + summary.scanned,
        0,
      ),
      deletedAggregateRoots: summaries.reduce(
        (total, summary) => total + summary.deleted,
        0,
      ),
      failedAggregateRoots: summaries.reduce(
        (total, summary) => total + summary.failed,
        0,
      ),
      collections: summaries,
    });
  },
)

trackAnalyticsEvent = onCall(
  callableOptions,
  async (request): Promise<{ tracked: boolean }> => {
    const actor = await requireVerifiedActiveUser(request);
    // This read intentionally precedes parsing, rate-limit consumption,
    // canonical lookups, proofs, and aggregate writes. A prepared v1→v2
    // cutover therefore leaves the client outbox retryable without consuming
    // its attempt budget or opening a write window that finalize could erase.
    await requireAnalyticsSchemaReady(db);
    const receivedAt = new Date();

    const analyticsRequest = parseAnalyticsRequest(request.data);
    const requestedOccurredAt = analyticsEventDate(
      analyticsRequest.occurredAtMilliseconds,
      receivedAt
    );
    const config = eventConfigs[analyticsRequest.name];
    const contentID = requiredSafeID(
      analyticsRequest.parameters.content_id,
      "content_id"
    );
    const canonicalContent = await resolveRateLimitedAnalyticsContent(
      actor.uid,
      config.contentType,
      contentID,
      receivedAt
    );
    const analyticsEvent = sanitizeAnalyticsEvent(analyticsRequest, canonicalContent);
    if (analyticsRequest.actionProof === undefined) {
      await requireLegacyAnalyticsActionProof(
        actor.uid,
        analyticsRequest.name,
        analyticsEvent.contentID,
        requestedOccurredAt
      );
    }
    const tracked = await commitAnalyticsEvent(
      actor.uid,
      analyticsRequest.consentID,
      analyticsRequest.name,
      analyticsEvent,
      analyticsRequest.actionProof,
      requestedOccurredAt,
      receivedAt
    );

    return {tracked};
  }
)

