trackDeletedUserAnalyticsAggregate = onDocumentDeleted(
  {
    document: "users/{userID}",
    region: "europe-west3",
    maxInstances: 10,
    retry: true,
  },
  async (event) => {
    const eventTime = new Date(event.time);
    const now = Number.isFinite(eventTime.getTime()) ? eventTime : new Date();
    const datedDocumentID = dailyDocumentIDFor(now);
    const eventReference = db
      .collection(schema.collections.deletedUserEvents)
      .doc(analyticsDeletionEventID(event.id));

    await Promise.all([
      eventReference.set({
        analyticsDay: datedDocumentID,
        deletedAt: Timestamp.fromDate(now),
        expiresAt: Timestamp.fromDate(analyticsActivityExpirationDate(now)),
      }),
      db.collection(schema.collections.userActivity).doc(event.params.userID).delete(),
    ]);
  }
)

trackRegisteredUserAnalyticsAggregate = onDocumentCreated(
  {
    document: "users/{userID}",
    region: "europe-west3",
    maxInstances: 10,
    retry: true,
  },
  async (event) => {
    // The profile's immutable createdAt is also used by the migration
    // baseline. Using CloudEvent delivery time here would put one account on
    // opposite sides of the cutover boundary when delivery is delayed.
    const registeredAt = dateValue(event.data?.data().createdAt);
    if (registeredAt === undefined) {
      throw new Error("Created user profile is missing an immutable createdAt timestamp.");
    }
    const eventReference = db
      .collection(schema.collections.registeredUserEvents)
      .doc(analyticsRegistrationEventID(event.id));

    await eventReference.set({
      analyticsDay: dailyDocumentIDFor(registeredAt),
      registeredAt: Timestamp.fromDate(registeredAt),
      userKey: analyticsRegistrationUserKey(event.params.userID),
      expiresAt: Timestamp.fromDate(analyticsActivityExpirationDate(registeredAt)),
    });
  }
)

activatePrivilegedMFAProtection = onCall(
  callableOptions,
  async (request): Promise<PrivilegedMFAActivationResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    if (!isTOTPAuthenticated(auth.token)) {
      throw new HttpsError(
        "failed-precondition",
        "Sign in with the authenticator before activating privileged protection."
      );
    }
    if (!isAppOwner(auth.permissions) && !isAppAdmin(auth.permissions)) {
      throw new HttpsError(
        "permission-denied",
        "Privileged MFA activation is available only to platform owners and admins."
      );
    }

    const userReference = db.collection("users").doc(auth.uid);
    const activatedAt = Timestamp.now();

    await db.runTransaction(async (transaction) => {
      const snapshot = await transaction.get(userReference);
      if (!snapshot.exists) {
        throw new HttpsError("not-found", "User profile does not exist.");
      }

      const permissions = userPermissionSnapshotFromData(auth.uid, snapshot.data());
      if (!isAppOwner(permissions) && !isAppAdmin(permissions)) {
        throw new HttpsError(
          "permission-denied",
          "The account no longer has a privileged platform role."
        );
      }

      if (permissions.requiresMultiFactorAuth === true) {
        return;
      }

      transaction.update(userReference, {
        requiresMultiFactorAuth: true,
        multiFactorAuthRequiredAt: activatedAt,
        multiFactorAuthRequiredMethod: "totp",
        updatedAt: FieldValue.serverTimestamp(),
      });
    });

    logger.info("Privileged TOTP protection activated", {
      actorUserId: auth.uid,
      method: "totp",
    });

    return {
      required: true,
      activatedAt: activatedAt.toDate().toISOString(),
    };
  }
)

uploadOrganizationContentCover = onCall(
  callableOptions,
  async (request): Promise<ContentCoverUploadResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const input = parseContentCoverUploadRequest(request.data);
    const collection = input.kind === "news" ? "news" : "events";
    const contentReference = db.collection(collection).doc(input.contentId);
    const contentSnapshot = await contentReference.get();
    if (!contentSnapshot.exists) {
      throw new HttpsError("not-found", "Content does not exist.");
    }

    const content = contentSnapshot.data();
    const organizationId = organizationIdFromContent(content);
    if (!organizationId) {
      if (!isOwner(auth.permissions) || content?.sourceType !== "app") {
        throw new HttpsError(
          "permission-denied",
          "Organization content publishing permissions are required."
        );
      }
    } else {
      const organizationSnapshot = await db.collection("organizations").doc(organizationId).get();
      if (!organizationSnapshot.exists) {
        throw new HttpsError("failed-precondition", "Content organization does not exist.");
      }
      assertCanManageOrganizationContent(
        auth.permissions,
        organizationSnapshot.data(),
        auth.uid
      );
    }

    const objectPath = `${collection}/${input.contentId}/cover.jpg`;
    const downloadToken = randomUUID();
    const bucket = adminStorage.bucket();
    const object = bucket.file(objectPath);

    await object.save(input.image, {
      resumable: false,
      contentType: "image/jpeg",
      metadata: {
        cacheControl: "public,max-age=3600",
        metadata: {firebaseStorageDownloadTokens: downloadToken},
      },
    });

    const imageURL = firebaseDownloadURL(bucket.name, objectPath, downloadToken);
    try {
      await contentReference.update({
        imageURL,
        updatedAt: FieldValue.serverTimestamp(),
      });
    } catch (error) {
      await object.delete({ignoreNotFound: true}).catch(() => undefined);
      throw error;
    }

    return {
      kind: input.kind,
      contentId: input.contentId,
      imageURL,
      byteCount: input.image.length,
    };
  }
)

deleteNews = onCall(
  callableOptions,
  async (request): Promise<DeletionResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const actor = auth.permissions;
    const newsId = requestResourceId(request.data, "newsId");
    const newsReference = db.collection("news").doc(newsId);
    const newsSnapshot = await newsReference.get();

    if (!newsSnapshot.exists && !isOwner(actor)) {
      throw new HttpsError("not-found", "News post does not exist.");
    }
    if (newsSnapshot.exists) {
      await assertCanDeleteOrganizationContent(actor.uid, newsSnapshot.data(), isOwner(actor));
    }

    await deleteNewsContent(newsId, newsSnapshot.data());
    const deletedAt = new Date().toISOString();
    logger.info("News content deletion completed.", {newsId, actorUserId: auth.uid});

    return {
      status: newsSnapshot.exists ? "deleted" : "alreadyDeleted",
      deletedAt,
    };
  }
)

deleteOrganization = onCall(
  callableOptions,
  async (request): Promise<DeletionResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const actor = auth.permissions;
    const organizationId = requestResourceId(request.data, "organizationId");
    if (organizationId === systemOrganizationId) {
      throw new HttpsError("failed-precondition", "The system organization cannot be deleted.");
    }

    const organizationReference = db.collection("organizations").doc(organizationId);
    let organizationExisted: boolean;
    if (isOwner(actor)) {
      const organizationSnapshot = await organizationReference.get();
      organizationExisted = organizationSnapshot.exists;
      await deleteOrganizationContent(organizationId, organizationExisted);
    } else {
      organizationExisted = await discardUnpublishedOrganizationRequest(
        organizationId,
        auth.uid
      );
      await deleteStoragePrefix(organizationStoragePrefix(organizationId));
      await db.recursiveDelete(organizationReference);
    }
    const deletedAt = new Date().toISOString();
    logger.info("Organization deletion completed.", {
      organizationId,
      actorUserId: auth.uid,
    });

    return {
      status: organizationExisted ? "deleted" : "alreadyDeleted",
      deletedAt,
    };
  }
)

migrateLegacyContentMedia = onSchedule(
  {
    schedule: "every day 03:30",
    timeZone: "Europe/Vienna",
    region: "europe-west3",
    timeoutSeconds: 540,
    memory: "512MiB",
  },
  async () => {
    const stateSnapshot = await migrationStateReference.get();
    const state = (stateSnapshot.data() ?? {}) as MigrationState;
    const summary: MigrationSummary = {migrated: 0, cleaned: 0, skipped: 0, failed: 0};

    if (state.newsCompleted !== true) {
      mergeSummary(summary, await migrateContentPage("news", state.newsCursor));
