cleanupStaleFeaturedBannerOrphans = onSchedule(
  {
    schedule: "every day 04:17",
    timeZone: "Europe/Vienna",
    region,
    timeoutSeconds: 300,
    memory: "512MiB",
  },
  async () => {
    const bucket = adminStorage.bucket();
    let pageToken: string | undefined;
    let scanned = 0;
    let deleted = 0;

    do {
      const [files, nextQuery] = await bucket.getFiles({
        prefix: "featuredBanners/",
        maxResults: 500,
        autoPaginate: false,
        pageToken,
      });
      pageToken = nextQuery?.pageToken;
      scanned += files.length;

      const bannerIds = Array.from(new Set(files
        .map((file) => featuredBannerIdFromObjectName(file.name))
        .filter((value): value is string => Boolean(value))));
      const existingIds = new Set<string>();
      for (let index = 0; index < bannerIds.length; index += 30) {
        const references = bannerIds.slice(index, index + 30)
          .map((bannerId) => db.collection("featuredBanners").doc(bannerId));
        if (references.length === 0) continue;
        const snapshots = await db.getAll(...references);
        snapshots.filter((snapshot) => snapshot.exists)
          .forEach((snapshot) => existingIds.add(snapshot.id));
      }

      const now = Date.now();
      for (const file of files) {
        const bannerId = featuredBannerIdFromObjectName(file.name);
        const createdAt = Date.parse(file.metadata.timeCreated ?? "");
        if (!bannerId || existingIds.has(bannerId) || !isStaleOrphan(createdAt, now)) {
          continue;
        }
        await file.delete({ignoreNotFound: true});
        deleted += 1;
      }
    } while (pageToken);

    console.info("Featured banner orphan cleanup completed.", {scanned, deleted});
  }
)

cleanupStaleContentMediaOrphans = onSchedule(
  {
    schedule: "every day 04:27",
    timeZone: "Europe/Vienna",
    region,
    timeoutSeconds: 540,
    memory: "512MiB",
  },
  async () => {
    let scanned = 0;
    let candidates = 0;
    let deleted = 0;
    for (const prefix of ["news/", "events/", "organizations/"]) {
      const result = await cleanupOrphanContentPrefix(prefix);
      scanned += result.scanned;
      candidates += result.candidates;
      deleted += result.deleted;
    }
    console.info("Content media orphan cleanup completed.", {
      scanned,
      candidates,
      deleted,
      gracePeriodHours: orphanGracePeriodMilliseconds / (60 * 60 * 1000),
    });
  }
)

cleanupContentPlanningDraftMediaOnTerminalState = onDocumentUpdated(
  {
    document: "users/{userId}/contentPlanningDrafts/{draftId}",
    region,
    retry: true,
  },
  async (event) => {
    const after = event.data?.after.data();
    if (!after || !isContentPlanningTerminalState(after.state) ||
        after.draftMediaCleanupStatus !== pendingCleanupStatus) {
      return;
    }
    await cleanupTerminalDraftMedia(event.params.userId, event.params.draftId);
  }
)

cleanupContentPlanningDraftMediaOnDelete = onDocumentDeleted(
  {
    document: "users/{userId}/contentPlanningDrafts/{draftId}",
    region,
    retry: true,
  },
  async (event) => {
    const data = event.data?.data();
    if (!data) return;
    const draftPath = generatedImageStoragePath(data);
    if (!draftPath) return;

    const expectedPrefix = contentPlanningDraftImagePrefix(
      event.params.userId,
      event.params.draftId
    );
    if (!draftPath.startsWith(expectedPrefix)) {
      logger.error("Refused to delete a planning image outside its exact draft prefix.", {
        userId: event.params.userId,
        draftId: event.params.draftId,
        draftPath,
      });
      return;
    }
    if (await draftMediaHasLiveReference(data, draftPath)) {
      logger.warn("Retained planning image because live content still references it.", {
        userId: event.params.userId,
        draftId: event.params.draftId,
        draftPath,
      });
      return;
    }
    await adminStorage.bucket().deleteFiles({prefix: expectedPrefix, force: true});
  }
)

