notifyFeedbackMessageCreated = onDocumentCreated(
  {
    document: "feedback/{feedbackId}/messages/{messageId}",
    region: "europe-west3",
    retry: true,
  },
  async (event) => {
    const message = event.data?.data() as FeedbackMessageData | undefined;
