acceptLegalDocument = onCall(
  callableOptions,
  async (request): Promise<AcceptLegalDocumentResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const legalRequest = parseAcceptLegalDocumentRequest(request.data);
    const userReference = db.collection("users").doc(auth.uid);
    const documentReference = db.collection("legalDocuments").doc(
      legalRequest.documentType
    );
    const versionReference = documentReference
      .collection("versions")
      .doc(legalRequest.version);
    const logReference = db.collection("legalAcceptanceLogs").doc();
    const committedAt = new Date().toISOString();

    await db.runTransaction(async (transaction) => {
      const [userSnapshot, documentSnapshot, versionSnapshot] = await Promise.all([
        transaction.get(userReference),
        transaction.get(documentReference),
        transaction.get(versionReference),
      ]);

      if (!userSnapshot.exists) {
        throw new HttpsError("permission-denied", "User profile does not exist.");
      }

      if (!documentSnapshot.exists) {
        throw new HttpsError("failed-precondition", "Legal document is not published.");
      }

      const documentData = documentSnapshot.data() ?? {};
      const activeVersion = documentData.activeVersion;
      if (activeVersion !== legalRequest.version) {
        throw new HttpsError("failed-precondition", "Requested version is not active.");
      }

      if (!versionSnapshot.exists) {
        throw new HttpsError("failed-precondition", "Legal version does not exist.");
      }

      const versionData = versionSnapshot.data() ?? {};
      if (versionData.status !== "published") {
        throw new HttpsError("failed-precondition", "Legal version is not published.");
      }

      transaction.update(userReference, userAcceptanceUpdate(legalRequest));
      transaction.set(logReference, {
        userId: auth.uid,
        documentType: legalRequest.documentType,
        version: legalRequest.version,
        acceptedAt: FieldValue.serverTimestamp(),
        appVersion: legalRequest.appVersion ?? null,
        locale: legalRequest.locale ?? null,
        contentHash: typeof versionData.contentHash === "string" ?
          versionData.contentHash :
          null,
        acceptedFromPlatform: legalRequest.acceptedFromPlatform ?? "ios",
      });
    });

    return {
      documentType: legalRequest.documentType,
      version: legalRequest.version,
      acceptedAt: committedAt,
    };
  }
)

listLegalEvidenceAccounts = onCall(
  callableOptions,
  async (request): Promise<ListLegalEvidenceAccountsResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertOwner(auth.permissions);
    const input = parseLegalEvidenceAccountRequest(request.data);

    if (input.query) {
      const normalizedQuery = normalizedSearch(input.query);
      const snapshot = await db.collection("users")
        .select("displayName", "fullName", "email", "createdAt")
        .get();
      const matches = snapshot.docs
        .filter((document) => accountMatchesSearch(document.id, document.data(), normalizedQuery))
        .sort((left, right) => timestampMillis(right.data().createdAt) - timestampMillis(left.data().createdAt));
      return {
        accounts: matches.slice(0, input.limit).map(accountFromDocument),
        nextCursor: null,
        totalMatches: matches.length,
      };
    }

    let query = db.collection("users")
      .orderBy("createdAt", "desc")
      .orderBy(FieldPath.documentId(), "desc")
      .limit(input.limit + 1);
    if (input.cursor) {
      query = query.startAfter(Timestamp.fromDate(new Date(input.cursor.createdAt)), input.cursor.userId);
    }
    const snapshot = await query.get();
    const page = snapshot.docs.slice(0, input.limit);
    const last = page.at(-1);
    const lastCreatedAt = last ? timestampISO(last.data().createdAt) : null;
    return {
      accounts: page.map(accountFromDocument),
      nextCursor: snapshot.size > input.limit && last && lastCreatedAt ? {
        userId: last.id,
        createdAt: lastCreatedAt,
      } : null,
      totalMatches: null,
    };
  }
)

getLegalEvidenceForUser = onCall(
  callableOptions,
  async (request): Promise<GetLegalEvidenceForUserResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertOwner(auth.permissions);
    const userId = parseLegalEvidenceUserRequest(request.data);
    const [user, legalLogs, analyticsReceipts] = await Promise.all([
      db.collection("users").doc(userId).get(),
      db.collection("legalAcceptanceLogs").where("userId", "==", userId).limit(maximumUserEvidenceEvents).get(),
      db.collection("analyticsConsentReceipts").where("userId", "==", userId).limit(maximumUserEvidenceEvents).get(),
    ]);
    if (!user.exists && legalLogs.empty && analyticsReceipts.empty) {
      throw new HttpsError("not-found", "The account and its legal evidence were not found.");
    }
    const identity = user.data() ?? {};
    const events = [
      ...(user.exists ? registrationEvents(user) : []),
      ...legalLogs.docs.flatMap(legalAcceptanceEvents),
      ...analyticsReceipts.docs.flatMap(analyticsConsentEvents),
    ]
      .map((event) => ({
        ...event,
        displayName: nullableString(identity.displayName) ?? nullableString(identity.fullName),
        email: nullableString(identity.email),
      }))
      .sort((left, right) => right.occurredAt.localeCompare(left.occurredAt));
    return {
      account: {
        userId,
        displayName: nullableString(identity.displayName) ?? nullableString(identity.fullName),
        email: nullableString(identity.email),
        createdAt: timestampISO(identity.createdAt),
      },
      events,
      generatedAt: new Date().toISOString(),
    };
  }
)

listLegalEvidence = onCall(
  callableOptions,
  async (request): Promise<ListLegalEvidenceResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertOwner(auth.permissions);
    const limit = parseLegalEvidenceLimit(request.data);

    const [users, legalLogs, analyticsReceipts] = await Promise.all([
      db.collection("users").orderBy("createdAt", "desc").limit(limit).get(),
      db.collection("legalAcceptanceLogs").orderBy("acceptedAt", "desc").limit(limit).get(),
      db.collection("analyticsConsentReceipts").orderBy("grantedAt", "desc").limit(limit).get(),
    ]);

    const events = [
      ...users.docs.flatMap(registrationEvents),
      ...legalLogs.docs.flatMap(legalAcceptanceEvents),
      ...analyticsReceipts.docs.flatMap(analyticsConsentEvents),
    ];
    const userIds = [...new Set(events.map((event) => event.userId))];
    const userSnapshots = userIds.length === 0 ?
      [] :
      await db.getAll(...userIds.map((userId) => db.collection("users").doc(userId)));
    const identities = new Map(
      userSnapshots.map((snapshot) => {
        const data = snapshot.data() ?? {};
        return [snapshot.id, {
          displayName: nullableString(data.displayName) ?? nullableString(data.fullName),
          email: nullableString(data.email),
        }] as const;
      })
    );

    return {
      events: events
        .map((event) => ({...event, ...(identities.get(event.userId) ?? {})}))
        .sort((left, right) => right.occurredAt.localeCompare(left.occurredAt))
        .slice(0, limit),
      generatedAt: new Date().toISOString(),
    };
  }
)

acceptOrganizationRules = onCall(
  callableOptions,
  async (request): Promise<AcceptOrganizationRulesResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const input = parseRequest(request.data);
    const documentReference = db.collection("legalDocuments").doc("organizationRules");
    const versionReference = documentReference.collection("versions").doc(input.version);
    const proofReference = db.collection("organizationCreationProofs").doc(input.organizationId);
    const logReference = db.collection("legalAcceptanceLogs").doc();
    const requestQuery = db.collection("organizations")
      .where("submittedByUserId", "==", auth.uid)
      .where("moderationStatus", "in", unpublishedOrganizationStatuses)
      .limit(maximumUnpublishedOrganizationRequests + 1);
    let committedAt = new Date();

    await db.runTransaction(async (transaction) => {
      const [documentSnapshot, versionSnapshot, proofSnapshot, requestSnapshot] = await Promise.all([
        transaction.get(documentReference),
        transaction.get(versionReference),
        transaction.get(proofReference),
        transaction.get(requestQuery),
      ]);

      if (!isOwner(auth.permissions)) {
        const otherRequestCount = requestSnapshot.docs.filter(
          (document) => document.id !== input.organizationId
        ).length;
        if (hasReachedOrganizationRequestLimit(otherRequestCount)) {
          throw new HttpsError(
            "resource-exhausted",
            "Resolve or delete an existing organization request before creating another.",
            {reason: "organization-request-limit", maximum: maximumUnpublishedOrganizationRequests}
          );
        }
      }

      if (!documentSnapshot.exists || documentSnapshot.data()?.activeVersion !== input.version) {
        throw new HttpsError("failed-precondition", "Requested organization rules are not active.");
      }
      const versionData = versionSnapshot.data();
      if (!versionSnapshot.exists || versionData?.status !== "published") {
        throw new HttpsError("failed-precondition", "Organization rules are not published.");
      }

      const existing = proofSnapshot.data();
      if (
        existing?.userId === auth.uid &&
        existing?.version === input.version &&
        existing?.organizationName === input.organizationName &&
        existing?.expiresAt instanceof Timestamp &&
        existing.expiresAt.toMillis() > Date.now()
      ) {
        committedAt = existing.acceptedAt instanceof Timestamp ?
          existing.acceptedAt.toDate() :
          committedAt;
        return;
      }

      committedAt = new Date();
      const expiresAt = Timestamp.fromMillis(
        committedAt.getTime() + proofValidityDays * 24 * 60 * 60 * 1_000
      );
      const evidence = {
        userId: auth.uid,
        documentType: "organizationRules",
        version: input.version,
        acceptedAt: FieldValue.serverTimestamp(),
        appVersion: input.appVersion ?? null,
        locale: input.locale ?? null,
        contentHash: typeof versionData?.contentHash === "string" ? versionData.contentHash : null,
        acceptedFromPlatform: input.acceptedFromPlatform ?? "ios",
        organizationId: input.organizationId,
        organizationName: input.organizationName,
      };

      transaction.set(proofReference, {
        ...evidence,
        expiresAt,
      });
      transaction.set(logReference, evidence);
    });

    return {
      organizationId: input.organizationId,
      version: input.version,
      acceptedAt: committedAt.toISOString(),
    };
  }
)

notifyEventUpdatedOnUpdate = onDocumentUpdated(
  { ...triggerOptions, document: "events/{eventId}" },
  async (event) => {
    const before = event.data?.before.data();
    const after = event.data?.after.data();
    if (before && after && !isCancellationTransition(before) && isCancellationTransition(after)) {
      await writeEventCancellationNotifications(event.params.eventId, await registeredUserIds(event.params.eventId), {
        eventData: after, cancelledAt: timestampField(after, "cancelledAt") ?? Timestamp.now(),
        requiresPopup: isSoon(after),
      });
      return;
    }
    if (!before || !after || isCancellationTransition(after) || !hasMeaningfulEventChange(before, after)) {
      return;
    }

    const eventId = event.params.eventId;
    const userIds = await registeredUserIds(eventId);
    if (userIds.length === 0) {
      return;
    }

    const versionPart = String(timestampField(after, "updatedAt")?.toMillis() ?? event.id);
    await writeEventNotifications(eventId, userIds, {
      type: "eventUpdated",
      severity: "info",
      requiresPopup: false,
      versionPart,
      metadata: {
        eventTitle: eventTitle(after),
        changedAt: versionPart,
      },
      eventData: after,
    });
  }
)

notifyEventCancelledOnDelete = onDocumentDeleted(
