    const deletedEvent = event.data?.data();
    const eventId = event.params.eventId;
    const userIds = await registeredUserIds(eventId);
    if (userIds.length === 0) {
      return;
    }

    const cancelledAt = Timestamp.now();
    const requiresPopup = isSoon(deletedEvent);
    await writeEventCancellationNotifications(eventId, userIds, {
      eventData: deletedEvent ?? {},
      cancelledAt,
      requiresPopup,
    });
  }
)

cancelEvent = onCall(
  callableOptions,
  async (request): Promise<EventCancellationResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const actorPermissions = auth.permissions;
    const cancellationRequest = parseEventCancellationRequest(request.data);
    const eventReference = db.collection("events").doc(cancellationRequest.eventId);
    const eventSnapshot = await eventReference.get();
    if (!eventSnapshot.exists) {
      throw new HttpsError("not-found", "Event does not exist.");
    }

    const eventData = eventSnapshot.data() ?? {};
    await assertCanCancelEvent(actorPermissions, eventData);

    const eventId = cancellationRequest.eventId;
    const userIds = await registeredUserIds(eventId);
    const cancelledAt = Timestamp.now();
    const requiresPopup = isSoon(eventData);
    if (userIds.length === 0) {
      await deleteEventContent(eventId, eventData);
      return {
        eventId,
        status: "deleted",
        recipientCount: 0,
        notificationCount: 0,
        pushRecipientCount: 0,
        cancelledAt: cancelledAt.toDate().toISOString(),
      };
    }

    await eventReference.update({
      moderationStatus: "archived",
      cancellationState: "cancelled",
      cancelledAt,
      cancelledBy: auth.uid,
      cancellationReason: cancellationRequest.reason ?? FieldValue.delete(),
      updatedAt: cancelledAt,
    });

    const notificationResult = await writeEventCancellationNotifications(eventId, userIds, {
      eventData,
      cancelledAt,
      requiresPopup,
    });
    // Dispatch is asynchronous; this response must not claim device delivery.
    const pushRecipientCount = 0;

    return {
      eventId,
      status: "cancelled",
      recipientCount: notificationResult.recipientCount,
      notificationCount: notificationResult.createdNotifications.length,
      pushRecipientCount,
      cancelledAt: cancelledAt.toDate().toISOString(),
    };
  }
)

createSystemAnnouncement = onCall(
  callableOptions,
  async (request): Promise<{ announcementId: string; recipientCount: number }> => {
    const auth = await requireVerifiedActiveUser(request);
    const actorPermissions = auth.permissions;
    assertOwner(actorPermissions);

    const announcementRequest = parseSystemAnnouncementRequest(request.data);
    const targetUserIds = await resolveSystemAnnouncementRecipients(announcementRequest);
    const recipients = await resolveNotificationRecipients(targetUserIds);
    const inboxRecipientIds = recipients.inboxRecipientIds;
    const announcementId = randomUUID();

    await db.collection("systemAnnouncements").doc(announcementId).set({
      id: announcementId,
      title: announcementRequest.title,
      message: announcementRequest.message,
      severity: announcementRequest.severity,
      requiresPopup: announcementRequest.requiresPopup,
      targetMode: announcementRequest.targetMode,
      targetUserIds: inboxRecipientIds,
      role: announcementRequest.role ?? null,
      actionType: announcementRequest.actionType,
      actionTargetId: announcementRequest.actionTargetId ?? null,
      url: announcementRequest.url ?? null,
      createdAt: Timestamp.now(),
      createdBy: auth.uid,
    });

    await Promise.all(inboxRecipientIds.map((userId) => writeUserNotification({
      notificationId: ["systemAnnouncement", announcementId, userId].join("_"),
      targetUserId: userId,
      type: "systemAnnouncement",
      title: announcementRequest.title,
      message: announcementRequest.message,
      severity: announcementRequest.severity,
      actionType: announcementRequest.actionType,
      actionTargetId: announcementRequest.actionTargetId ?? announcementRequest.url,
      requiresPopup: announcementRequest.requiresPopup,
      actorUserId: auth.uid,
      sourceType: "system",
      sourceId: announcementId,
      metadata: {
        announcementId,
        url: announcementRequest.url ?? null,
      },
      dedupeKey: `systemAnnouncement:${announcementId}:${userId}`,
    })));

    return {
      announcementId,
      recipientCount: inboxRecipientIds.length,
    };
  }
)

notifyEventRegistrationConfirmedOnCreate = onDocumentCreated(
  { ...triggerOptions, document: "registrations/{registrationId}" },
  async (event) => {
    const registration = event.data?.data();
    const eventId = stringField(registration, "eventId");
    const userId = stringField(registration, "userId");

    if (!eventId || !userId) {
      return;
    }

    const eventSnapshot = await db.collection("events").doc(eventId).get();
    const eventData = eventSnapshot.data();
    if (!eventSnapshot.exists || !isPublicApprovedEvent(eventData)) {
      return;
    }

    const recipients = await resolveNotificationRecipients([userId]);
    if (!recipients.inboxRecipientIds.includes(userId)) {
      return;
    }

    const userSnapshot = await db.collection("users").doc(userId).get();
    const eventTitle = stringField(eventData, "title") ?? "Event";
    const copy = eventRegistrationCopy(
      eventTitle,
      notificationLanguage(userSnapshot.data())
    );
    const notificationId = `eventRegistrationConfirmed_${event.id}_${userId}`;

    await writeUserNotification({
      notificationId,
      targetUserId: userId,
      type: "eventRegistrationConfirmed",
      title: copy.title,
      message: copy.body,
      severity: "info",
      actionType: "openEvent",
      actionTargetId: eventId,
      requiresPopup: false,
      sourceType: "event",
      sourceId: eventId,
      metadata: {
        eventId,
        eventTitle,
        route: "openEvent",
        routeTargetId: eventId,
      },
      dedupeKey: notificationId,
    });

  }
)

sendTestPushNotification = onCall(
  callableOptions,
  async (request): Promise<TestPushResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertCanSendTestPush(auth.permissions);
    const recipients = await resolveNotificationRecipients([auth.uid]);
    if (!recipients.pushRecipientIds.includes(auth.uid)) {
      throw new HttpsError(
        "failed-precondition",
        "Push notifications are disabled for this account."
      );
    }

    const registrations = await db.collection("users")
      .doc(auth.uid)
      .collection("notificationPushTokens")
      .get();
    if (registrations.empty) {
      throw new HttpsError(
        "failed-precondition",
        "No notification-enabled device is registered for this account."
      );
    }

    const badge = await unreadNotificationCount(auth.uid);
    const providerErrors = new Set<string>();
    const delivery = await sendPushToRegistrationDocuments(registrations.docs, {
      notification: {
        title: "Ukrainian Community",
        body: "Test notification delivered successfully.",
      },
      data: buildNotificationDataPayload({
        notificationId: `pushTest_${auth.uid}_${Date.now()}`,
        type: "systemAnnouncement",
        sourceType: "system",
        sourceId: "pushTest",
        actionType: "none",
      }),
      apns: {
        payload: {
          aps: {
            badge, // A diagnostic push does not create an unread inbox record.
            sound: "default",
          },
        },
      },
    }, undefined, async (_ids, result) => {
      if (result.error?.code) providerErrors.add(result.error.code);
    });

    if (delivery.successCount === 0) {
      throw new HttpsError(
        "unavailable",
        "Firebase rejected the test notification.",
        {providerErrorCodes: [...providerErrors], targetCount: delivery.targetCount}
      );
    }
    return delivery;
  }
)

deliverInboxNotificationPushOnCreate = onDocumentCreated(
  {
    ...triggerOptions,
    document: "users/{userId}/notificationInbox/{notificationId}",
  },
  async (event) => {
    const notification = event.data?.data();
    const type = enumString(notification?.type, notificationTypes);
    if (!notification || !type || !shouldDeliverInboxNotificationPush(type, notification.metadata)) {
      return;
    }

    const metadata = recordValue(notification.metadata);
    if (!await canReceiveScopedNotification(event.params.userId, metadata)) return;

    const userId = event.params.userId;
    const recipients = await resolveNotificationRecipients([userId], {
      // Account restrictions are already committed when this trigger runs.
      // The affected user must still receive the one push that explains why
      // access changed, provided they explicitly enabled notifications.
      allowRestrictedPush: type === "accountStatusChanged",
    });
    if (!recipients.pushRecipientIds.includes(userId)) {
      return;
    }

    const tokenSnapshot = await db.collection("users")
      .doc(userId)
      .collection("notificationPushTokens")
      .get();
    if (tokenSnapshot.empty) {
      console.info("Notification push skipped because the user has no registered device.", {
        userId,
        notificationId: event.params.notificationId,
        type,
      });
      return;
    }

    const sourceType = enumString(notification.sourceType, sourceTypes) ?? "system";
    const sourceId = stringValue(notification.sourceId) ?? event.params.notificationId;
    const actionType = enumString(notification.actionType, actionTypes) ?? "none";
    const actionTargetId = stringValue(notification.actionTargetId);
    const route = stringValue(metadata.route);
    const routeTargetId = stringValue(metadata.routeTargetId);
    const title = stringValue(notification.title) ?? fallbackTitle(type);
    const body = stringValue(notification.message) ?? title;
    const localizedAlert = localizedAlertKeys(type, metadata);
    await deliverPushDurably(event.data!.ref, {
      notification: { title, body },
      data: buildNotificationDataPayload({
        notificationId: event.params.notificationId,
        type,
        sourceType,
        sourceId,
        actionType,
        actionTargetId,
        route,
        routeTargetId,
      }),
      apns: {
        payload: {
          aps: {
            alert: {
              titleLocKey: localizedAlert.titleLocKey,
              locKey: localizedAlert.bodyLocKey,
              locArgs: Array.isArray(metadata.bodyLocArgs)
                ? metadata.bodyLocArgs.filter((value): value is string => typeof value === "string") : [],
            },
            sound: "default",
          },
        },
      },
    }, tokenSnapshot.docs);

  }
)

notifyLegalDocumentsUpdatedOnPublish = onDocumentUpdated(
  {
    ...triggerOptions,
    document: "legalDocuments/{documentType}",
  },
  async (event) => {
    const before = event.data?.before.data();
    const after = event.data?.after.data();
    const activeVersion = stringValue(after?.activeVersion);
    if (!after || !activeVersion || before?.activeVersion === activeVersion || after.status !== "published") {
      return;
    }

    const documentType = event.params.documentType;
    let lastUserId: string | undefined;
    do {
      let query = db.collection("users")
        .orderBy(FieldPath.documentId())
        .limit(100);
      if (lastUserId) {
        query = query.startAfter(lastUserId);
      }
      const page = await query.get();
      if (page.empty) {
        return;
      }

      const recipients = await resolveNotificationRecipients(page.docs.map((document) => document.id));
      await Promise.all(recipients.inboxRecipientIds.map((userId) => writeUserNotification({
        notificationId: `legalDocumentsUpdated_${documentType}_${activeVersion}_${userId}`,
        targetUserId: userId,
        type: "legalDocumentsUpdated",
        title: "Legal documents updated",
        message: stringValue(after.changeSummary) ?? "Please review the updated legal documents.",
        severity: after.requiresAcceptance === true ? "warning" : "info",
        actionType: "openLegalDocuments",
        actionTargetId: documentType,
        requiresPopup: false,
        actorUserId: stringValue(after.publishedBy),
        sourceType: "legal",
        sourceId: documentType,
        metadata: {
          documentType,
          activeVersion,
          route: "openLegalDocuments",
          routeTargetId: documentType,
        },
        dedupeKey: `legalDocumentsUpdated:${documentType}:${activeVersion}:${userId}`,
      })));

      lastUserId = page.docs.at(-1)?.id;
      if (page.size < 100) {
        return;
      }
    } while (lastUserId !== undefined);
  }
)

notifyReportReviewedOnUpdate = onDocumentUpdated(
  {
    ...triggerOptions,
    document: "feedback/{feedbackId}",
  },
  async (event) => {
    const before = event.data?.before.data();
    const after = event.data?.after.data();
    const userId = stringValue(after?.userId);
    if (!after) return;
    if (after.dsaCase) {
      if (after.status === "closed" && before?.status !== "closed") {
        const canonical = await db.collection("dsaCases").doc(event.params.feedbackId).get();
        const canonicalStatus = stringValue(canonical.data()?.status);
        if (!canonical.exists || !["decided", "appealDecided"].includes(canonicalStatus ?? "")) {
          await event.data?.after.ref.update({
            status: "open",
            updatedAt: FieldValue.serverTimestamp(),
            unreadForOwner: true,
          });
        }
      }
      return;
    }
    if (after.type !== "report" || after.status !== "closed" || before?.status === "closed" || !userId) {
      return;
    }

    await writeUserNotification({
      notificationId: `reportReviewed_${event.params.feedbackId}_${userId}`,
      targetUserId: userId,
      type: "reportReviewed",
      title: "Report reviewed",
      message: "Your report has been reviewed and closed.",
      severity: "info",
      actionType: "openFeedback",
      actionTargetId: event.params.feedbackId,
      requiresPopup: false,
      sourceType: "feedback",
      sourceId: event.params.feedbackId,
      metadata: {
        reportId: event.params.feedbackId,
        route: "openFeedback",
        routeTargetId: event.params.feedbackId,
      },
      dedupeKey: `reportReviewed:${event.params.feedbackId}:${userId}`,
    });
  }
)

