createOrganizationPhotoMetadata = onCall(
  callableOptions,
  async (request): Promise<OrganizationPhotoMutationResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const input = parseCreateOrganizationPhotoRequest(request.data);
    const organizationReference = db.collection("organizations").doc(input.organizationId);
    const photos = organizationReference.collection("photos");
    const photoReference = photos.doc(input.photoId);

    return db.runTransaction(async (transaction) => {
      const [organizationSnapshot, photoSnapshot] = await transaction.getAll(
        organizationReference,
        photoReference
      );
      if (!organizationSnapshot.exists) {
        throw new HttpsError("not-found", "Organization does not exist.");
      }

      assertCanManageOrganizationPhotos(
        auth.permissions,
        organizationSnapshot.data(),
        auth.uid
      );

      const photoSnapshotList = await transaction.get(
        photos.limit(maximumOrganizationPhotoCount + 1)
      );
      const currentCount = photoSnapshotList.size;

      if (photoSnapshot.exists) {
        return existingPhotoResponse(
          input.organizationId,
          input.photoId,
          currentCount,
          photoSnapshot.data()
        );
      }

      if (currentCount >= maximumOrganizationPhotoCount) {
        throw new HttpsError(
          "resource-exhausted",
          `An organization can contain at most ${maximumOrganizationPhotoCount} photos.`
        );
      }

      const now = Timestamp.now();
      transaction.create(photoReference, {
        id: input.photoId,
        organizationId: input.organizationId,
        imageURL: input.imageURL,
        caption: input.caption ?? null,
        uploadedBy: auth.uid,
        createdAt: now,
        updatedAt: null,
      });
      transaction.update(organizationReference, {
        photoCount: currentCount + 1,
      });

      return {
        organizationId: input.organizationId,
        photoId: input.photoId,
        photoCount: currentCount + 1,
        didChange: true,
        uploadedBy: auth.uid,
        createdAt: now.toDate().toISOString(),
      };
    });
  }
)

deleteOrganizationPhotoMetadata = onCall(
  callableOptions,
  async (request): Promise<OrganizationPhotoMutationResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    const input = parseDeleteOrganizationPhotoRequest(request.data);
    const organizationReference = db.collection("organizations").doc(input.organizationId);
    const photos = organizationReference.collection("photos");
    const photoReference = photos.doc(input.photoId);

    return db.runTransaction(async (transaction) => {
      const [organizationSnapshot, photoSnapshot] = await transaction.getAll(
        organizationReference,
        photoReference
      );
      if (!organizationSnapshot.exists) {
        throw new HttpsError("not-found", "Organization does not exist.");
      }

      assertCanManageOrganizationPhotos(
        auth.permissions,
        organizationSnapshot.data(),
        auth.uid
      );

      const photoSnapshotList = await transaction.get(
        photos.limit(maximumOrganizationPhotoCount + 1)
      );
      const currentCount = photoSnapshotList.size;
      if (!photoSnapshot.exists) {
        return {
          organizationId: input.organizationId,
          photoId: input.photoId,
          photoCount: currentCount,
          didChange: false,
        };
      }

      const nextCount = Math.max(0, currentCount - 1);
      transaction.delete(photoReference);
      transaction.update(organizationReference, {photoCount: nextCount});

      return {
        organizationId: input.organizationId,
        photoId: input.photoId,
        photoCount: nextCount,
        didChange: true,
      };
    });
  }
)

cleanupAbandonedOrganizationRequests = onSchedule(
  {
    schedule: "every day 04:23",
    timeZone: "Europe/Vienna",
    region: "europe-west3",
    timeoutSeconds: 540,
    memory: "512MiB",
    retryCount: 3,
  },
  async () => {
    const now = Date.now();
    const warningCutoff = Timestamp.fromMillis(
      now - (organizationRequestRetentionDays - organizationRequestWarningLeadDays) * millisecondsPerDay
    );
    const failures: unknown[] = [];
    let resumed = 0;
    let warned = 0;
    let deleted = 0;

    const outstandingJobs = await db.collection(organizationRequestRetentionJobCollection)
      .where("status", "in", [...resumableJobStatuses])
      .limit(pageSize)
      .get();
    for (const job of outstandingJobs.docs) {
      try {
        const result = await processOrganizationRequestRetentionJob(job.id, now);
        if (result === "completed") resumed += 1;
      } catch (error) {
        failures.push(error);
        logger.error("Failed to resume organization request retention job.", {
          jobId: job.id,
          error: retentionErrorMessage(error),
        });
      }
    }

    for (const status of eligibleStatuses) {
      let cursor: QueryDocumentSnapshot<DocumentData> | undefined;
      do {
        let query = db.collection("organizations")
          .where("moderationStatus", "==", status)
          .where("updatedAt", "<=", warningCutoff)
          .orderBy("updatedAt", "asc")
          .limit(pageSize);
        if (cursor) query = query.startAfter(cursor);
        const snapshot = await query.get();

        for (const candidate of snapshot.docs) {
          try {
            const result = await processOrganizationRequest(candidate.id, now);
            if (result === "warning") warned += 1;
            if (result === "expired") deleted += 1;
          } catch (error) {
            failures.push(error);
            logger.error("Failed to process organization request retention candidate.", {
              organizationId: candidate.id,
              error: retentionErrorMessage(error),
            });
          }
        }
        cursor = snapshot.docs.at(-1);
      } while (cursor);
    }

    logger.info("Organization request retention completed.", {
      resumed,
      warned,
      deleted,
      failed: failures.length,
    });
    if (failures.length > 0) {
      throw new Error(`Organization request retention failed for ${failures.length} item(s).`);
    }
  }
)

