setUserBlocked = onCall(
  callableOptions,
  async (request): Promise<UserBlockResponse> => {
    const actor = await requireVerifiedActiveUser(request);
    const input = parseUserBlockRequest(request.data);
    if (input.targetUserId === actor.uid) {
      throw new HttpsError("failed-precondition", "You cannot block your own account.");
    }

    const [targetSnapshot, publicProfileSnapshot] = await Promise.all([
      db.collection("users").doc(input.targetUserId).get(),
      db.collection("publicProfiles").doc(input.targetUserId).get(),
    ]);
    if (!targetSnapshot.exists) {
      throw new HttpsError("not-found", "The target user does not exist.");
    }

    const target = targetSnapshot.data() ?? {};
    const publicProfile = publicProfileSnapshot.data() ?? {};
    const targetIsDeactivated = target.accountStatus === "deactivated"
      || target.blockState === "deactivated";
    if (targetIsDeactivated) {
      throw new HttpsError("not-found", "The target user is no longer active.");
    }

    const displayName = normalizedDisplayName(
      publicProfile.displayName ?? target.displayName ?? target.fullName
    );
    const avatarURL = optionalAvatarURL(publicProfile.avatarURL ?? target.avatarURL);
    const reference = db.doc(userBlockDocumentPath(actor.uid, input.targetUserId));
    const updatedAt = Timestamp.now();

    await db.runTransaction(async (transaction) => {
      const existing = await transaction.get(reference);
      if (!input.isBlocked) {
        if (existing.exists) {
          transaction.delete(reference);
        }
        return;
      }

      transaction.set(reference, {
        id: input.targetUserId,
        targetUserId: input.targetUserId,
        displayName,
        avatarURL: avatarURL ?? null,
        blockedAt: existing.data()?.blockedAt ?? updatedAt,
        updatedAt,
      });
    });

    return {
      targetUserId: input.targetUserId,
      isBlocked: input.isBlocked,
      displayName,
      avatarURL,
      updatedAt: updatedAt.toDate().toISOString(),
    };
  }
)

writeClientDiagnostic = onCall(
  callableOptions,
  async (request): Promise<{id: string; createdAt: string}> => {
    const actor = await requireVerifiedActiveUser(request);
    const input = parseDiagnostic(request.data);
    const createdAt = Timestamp.now();
    const reference = db.collection("systemLogs").doc();
    const actorRole = normalizedActorRole(actor.permissions.globalRole);

    const quotaReference = db.collection("systemLogDiagnosticRateLimits").doc(actor.uid);
    await db.runTransaction(async (transaction) => {
      const quotaSnapshot = await transaction.get(quotaReference);
      const quota = quotaSnapshot.data();
      const previousStart = quota?.windowStartedAt instanceof Timestamp ?
        quota.windowStartedAt.toMillis() : 0;
      const isCurrentWindow = createdAt.toMillis() - previousStart < quotaWindowMilliseconds;
      const previousCount = isCurrentWindow && typeof quota?.count === "number" ? quota.count : 0;
      if (previousCount >= quotaMaximumWrites) {
        throw new HttpsError("resource-exhausted", "Diagnostic log rate limit exceeded.");
      }

      transaction.set(quotaReference, {
        windowStartedAt: isCurrentWindow ? quota?.windowStartedAt : createdAt,
        count: previousCount + 1,
        updatedAt: createdAt,
      });
      transaction.set(reference, {
        id: reference.id,
        createdAt,
        category: "diagnostics",
        severity: input.severity,
        severityRank: severityRank(input.severity),
        eventType: input.eventType,
        actorUserId: actor.uid,
        actorRole,
        targetType: input.targetType,
        summary: input.summary,
        outcome: "failed",
        isReviewed: false,
        metadata: input.metadata,
        retentionPolicy: "technicalError",
        isAppAdminReadable: actorRole !== "owner",
        ...optionalFields(input),
      });
    });

    return {id: reference.id, createdAt: createdAt.toDate().toISOString()};
  }
)

clearSystemLogs = onCall(
  callableOptions,
  async (request): Promise<{deletedCount: number}> => {
    if (!isEmptyRequest(request.data)) {
      throw new HttpsError("invalid-argument", "Request payload must be empty.");
    }

    const actor = await requireVerifiedActiveUser(request);
    assertOwner(actor.permissions);

    await auditLogRef().set(buildAuditLog({
      actionType: "systemLogsClearRequested",
      targetUserId: actor.uid,
      performedBy: actor.uid,
      reason: "Owner requested clearing the system journal.",
      previousValue: {status: "available"},
      newValue: {status: "clearRequested"},
    }));

    let deletedCount = 0;
    while (deletedCount < maximumDeletedLogs) {
      const snapshot = await db.collection("systemLogs").limit(deleteBatchSize).get();
      if (snapshot.empty) break;

      const writer = db.bulkWriter();
      for (const document of snapshot.docs) {
        writer.delete(document.ref);
      }
      await writer.close();
      deletedCount += snapshot.size;
    }

    if (deletedCount >= maximumDeletedLogs) {
      const remaining = await db.collection("systemLogs").limit(1).get();
      if (!remaining.empty) {
        throw new HttpsError(
          "resource-exhausted",
          "The journal exceeded the safe limit. Run the operation again to continue."
        );
      }
    }

    try {
      await auditLogRef().set(buildAuditLog({
        actionType: "systemLogsCleared",
        targetUserId: actor.uid,
        performedBy: actor.uid,
        reason: "Owner cleared the system journal.",
        previousValue: {systemLogCount: deletedCount},
        newValue: {systemLogCount: 0},
      }));
    } catch (error) {
      // The clear request is already audited. Do not report the destructive
      // operation as failed after the system logs were successfully removed.
      console.error("Failed to write systemLogsCleared completion audit.", error);
    }

    return {deletedCount};
  }
)

