searchManagedUsers = onCall(
  callableOptions,
  async (request): Promise<UserSearchResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertCanManageUsers(auth.permissions);

    const data = request.data as Partial<UserSearchRequest> | undefined;
    const query = normalizeUserSearchQuery(data?.query);
    const limit = normalizedLimit(data?.limit);
    const snapshot = await db.collection("users")
      .select(...searchableFields)
      .get();

    const matchingIds = snapshot.docs
      .filter((document) => userDocumentMatchesSearch(document.id, document.data(), query))
      .map((document) => document.id);

    return {
      userIds: matchingIds.slice(0, limit),
      totalMatches: matchingIds.length,
    };
  }
)

getManagedUserSecurityMetadata = onCall(
  callableOptions,
  async (request): Promise<UserSecurityMetadataResponse> => {
    const auth = await requireVerifiedActiveUser(request);
    assertCanManageUsers(auth.permissions);

    const data = request.data as Partial<UserSecurityMetadataRequest> | undefined;
    const targetUserId = requiredTargetUserId(data?.targetUserId);

    try {
      const user = await adminAuth.getUser(targetUserId);
      return {
        targetUserId,
        emailVerified: user.emailVerified,
        authDisabled: user.disabled,
        creationTime: user.metadata.creationTime ?? null,
        lastSignInTime: user.metadata.lastSignInTime ?? null,
        providerIds: [...new Set(user.providerData.map((provider) => provider.providerId))].sort(),
      };
    } catch (error) {
      const code = typeof error === "object" && error !== null && "code" in error
        ? String(error.code)
        : "";
      if (code === "auth/user-not-found") {
        throw new HttpsError("not-found", "Target authentication account does not exist.");
      }
      throw error;
    }
  }
)

updateUserPresence = onCall(options, async (request) => {
  const auth = requireVerifiedAuth(request);
  const update = parsePresenceUpdate(request.data, auth.uid);
  await writeUserPresence(auth.uid, update);
  return {accepted: true};
})

getManagedUserPresence = onCall(options, async (request) => {
  const auth = await requireVerifiedActiveUser(request);
  assertCanManageUsers(auth.permissions);
  const targetUserId = request.data?.targetUserId;
  if (typeof targetUserId !== "string" || !targetUserId.length || targetUserId.includes("/")
      || targetUserId.length > 128) {
    throw new HttpsError("invalid-argument", "A valid targetUserId is required.");
  }
  const user = db.collection("users").doc(targetUserId);
  const [profile, snapshot] = await db.getAll(user, user.collection("privatePresence").doc("current"));
  if (!profile.exists) throw new HttpsError("not-found", "User profile does not exist.");
  return presenceResponse(targetUserId, presenceState(snapshot.data()), Date.now(),
    isActiveUser(userPermissionSnapshotFromData(targetUserId, profile.data())));
})
